            // Try getting instruction name by ID
            const char *name = cs_insn_name(handle, insn[i].id);
            printf("ID %d -> %s\n", insn[i].id, name ? name : "NULL");
        }
        cs_free(insn, count);
    }

    cs_close(&handle);
    return 0;
}
